#!/usr/bin/env python3
import sys, os, re, glob, stat
from html.parser import HTMLParser
from urllib.parse import urljoin, quote

HELP_TEXT = '''
# html2markdown - convert html to markdown [version dev]

Convert HTML to Markdown. Even works with entire websites!

## Basics

By default the "Commonmark" Plugin will be enabled. You can customize the options,
for example changing the appearance of bold with --opt-strong-delimiter="__"

Other Plugins can also be enabled. For example "GitHub Flavored Markdown" (GFM)
extends Commonmark with more features.

## Relative / Absolute Links

Use --domain="https://example.com" to convert *relative* links to *absolute* links.
The same also works for images.

## Escaping

Some characters have a special meaning in markdown. The library escapes these — if necessary.
See the documentation for more info.

## Security

Once you convert this markdown *back* to HTML you need to be careful of malicious content. 
Use a HTML sanitizer before displaying the HTML in the browser!


## Examples

    echo "<strong>important</strong>" | html2markdown

    curl --no-progress-meter http://example.com | html2markdown


    html2markdown --input file.html --output file.md

    html2markdown --input "src/*.html" --output "dist/"


## Flags

    -v, --version
        show the version of html2markdown and exit

    --help

    --input PATH
        Input file, directory, or glob pattern (instead of stdin)

    --output PATH
        Output file or directory (instead of stdout)

    --output-overwrite
        Replace existing files

    If --input is a directory or glob pattern, --output must be a directory.



    --domain
        The url of the web page, used to convert relative links to absolute links.

    --exclude-selector
        css query selector to exclude parts of the input

    --include-selector
        css query selector to only include parts of the input

    --opt-strong-delimiter
        Make bold text. Should <strong> be indicated by two asterisks or two underscores?
        "**" or "__" (default: "**")

    --opt-table-cell-padding-behavior
        [for --plugin-table] whether cells in the tables should include extra padding for visual continuity: "aligned", "minimal", or "none"

    --opt-table-header-promotion
        [for --plugin-table] first row should be treated as a header

    --opt-table-newline-behavior
        [for --plugin-table] how tables containing newlines should be handled: "skip" or "preserve"

    --opt-table-presentation-tables
        [for --plugin-table] whether tables with role="presentation" should be converted

    --opt-table-skip-empty-rows
        [for --plugin-table] omit empty rows from the output

    --opt-table-span-cell-behavior
        [for --plugin-table] how colspan/rowspan should be rendered: "empty" or "mirror"

    --plugin-strikethrough
        enable the plugin ~~strikethrough~~

    --plugin-table
        enable the plugin table



For more information visit the documentation:
https://github.com/Johanneskaufmann/html-to-markdown
'''

VERSION_TEXT = '''html2markdown

GitVersion:  dev
GitCommit:   none
BuildDate:   unknown
'''

BR = '\ue000'

class Options:
    def __init__(self):
        self.input = None
        self.output = None
        self.output_overwrite = False
        self.domain = None
        self.include_selectors = []
        self.exclude_selectors = []
        self.strong_delim = '**'
        self.plugin_strikethrough = False
        self.plugin_table = False
        self.table_cell_padding = 'aligned'
        self.table_header_promotion = False
        self.table_newline_behavior = 'skip'
        self.table_presentation_tables = False
        self.table_skip_empty_rows = False
        self.table_span_cell_behavior = 'empty'

class Node:
    __slots__ = ('tag','attrs','children','text','parent')
    def __init__(self, tag=None, attrs=None, text=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []
        self.text = text
        self.parent = None
    def append(self, child):
        child.parent = self
        self.children.append(child)
    def is_text(self):
        return self.tag is None
    def attr(self, name, default=''):
        return self.attrs.get(name.lower(), default)

VOID_TAGS = set('area base br col embed hr img input link meta param source track wbr command keygen menuitem'.split())
SKIP_TAGS = set('script style head title iframe noframes template svg math canvas'.split())
BLOCK_TAGS = set('address article aside blockquote body center dd details dialog dir div dl dt fieldset figcaption figure footer form h1 h2 h3 h4 h5 h6 header hgroup hr html li main menu nav ol p pre section summary table tbody td tfoot th thead tr ul'.split())
INLINE_TAGS = set('a abbr acronym b bdi bdo big br button cite code data del dfn em font i img input ins kbd label mark q rp rt ruby s samp small span strike strong sub sup time tt u var'.split())

class TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = Node('root')
        self.stack = [self.root]
        self.skip_stack = []
    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if self.skip_stack:
            if tag not in VOID_TAGS:
                self.skip_stack.append(tag)
            return
        if tag in SKIP_TAGS:
            if tag not in VOID_TAGS:
                self.skip_stack.append(tag)
            return
        d = {}
        for k,v in attrs:
            if k is not None:
                d[k.lower()] = '' if v is None else v
        n = Node(tag, d)
        self.stack[-1].append(n)
        if tag not in VOID_TAGS:
            self.stack.append(n)
    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        # handle_starttag does not push void tags; if an unknown self-closing tag was pushed, pop it
        tag = tag.lower()
        if not self.skip_stack and tag not in VOID_TAGS and len(self.stack) > 1 and self.stack[-1].tag == tag:
            self.stack.pop()
    def handle_endtag(self, tag):
        tag = tag.lower()
        if self.skip_stack:
            if tag == self.skip_stack[-1]:
                self.skip_stack.pop()
            return
        for i in range(len(self.stack)-1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return
    def handle_data(self, data):
        if self.skip_stack:
            return
        if data:
            self.stack[-1].append(Node(text=data))

# ---------------- CLI errors ----------------

def err(msg, extra=None):
    sys.stderr.write('\nerror: ' + msg + '\n\n')
    if extra:
        sys.stderr.write(extra)
    return 1

CLI_HINT = '''Here is how you can use the CLI:

    echo "<strong>important</strong>" | html2markdown

'''
GLOB_HINT = '''Here is how you can use a glob to match multiple files:

    html2markdown --input "src/*.html" --output "dist/"

'''
DIR_HINT = '''The --output must end with "/" to indicate a directory

'''

BOOL_TRUE = {'1','t','true','y','yes'}
BOOL_FALSE = {'0','f','false','n','no'}

def parse_bool_value(s):
    sl = s.lower()
    if sl in BOOL_TRUE: return True
    if sl in BOOL_FALSE: return False
    # Go's flag package would reject this; default to true for forgiving behavior.
    return True

def parse_args(argv):
    opts = Options()
    i = 0
    positionals = []
    string_once = {'input','output','domain','opt-strong-delimiter','opt-table-cell-padding-behavior','opt-table-newline-behavior','opt-table-span-cell-behavior'}
    seen = {}

    def flag_value(name, arg):
        nonlocal i
        prefix = '--' + name
        if arg == prefix:
            if i + 1 >= len(argv):
                raise ValueError('flag needs an argument: -' + name)
            i += 1
            return argv[i]
        if arg.startswith(prefix + '='):
            return arg[len(prefix)+1:]
        return None

    while i < len(argv):
        a = argv[i]
        if a == '--':
            positionals.extend(argv[i+1:])
            break
        if a in ('-h','--help') or a.startswith('--help='):
            sys.stdout.write(HELP_TEXT)
            raise SystemExit(0)
        if a in ('-v','--version') or a.startswith('--version='):
            sys.stdout.write(VERSION_TEXT)
            raise SystemExit(0)
        handled = False
        for name in ('input','output','domain','include-selector','exclude-selector','opt-strong-delimiter','opt-table-cell-padding-behavior','opt-table-newline-behavior','opt-table-span-cell-behavior'):
            if a == '--'+name or a.startswith('--'+name+'='):
                val = flag_value(name, a)
                if name in string_once:
                    if name in seen:
                        raise ValueError(f'invalid value "{val}" for flag -{name}: another value has already been set')
                    seen[name] = True
                if name == 'input': opts.input = val
                elif name == 'output': opts.output = val
                elif name == 'domain': opts.domain = val
                elif name == 'include-selector': opts.include_selectors.append(val)
                elif name == 'exclude-selector': opts.exclude_selectors.append(val)
                elif name == 'opt-strong-delimiter': opts.strong_delim = val
                elif name == 'opt-table-cell-padding-behavior': opts.table_cell_padding = val
                elif name == 'opt-table-newline-behavior': opts.table_newline_behavior = val
                elif name == 'opt-table-span-cell-behavior': opts.table_span_cell_behavior = val
                handled = True
                break
        if handled:
            i += 1
            continue
        bool_names = ('output-overwrite','plugin-strikethrough','plugin-table','opt-table-header-promotion','opt-table-presentation-tables','opt-table-skip-empty-rows')
        for name in bool_names:
            if a == '--'+name or a.startswith('--'+name+'='):
                if a.startswith('--'+name+'='):
                    val = parse_bool_value(a.split('=',1)[1])
                else:
                    val = True
                if name == 'output-overwrite': opts.output_overwrite = val
                elif name == 'plugin-strikethrough': opts.plugin_strikethrough = val
                elif name == 'plugin-table': opts.plugin_table = val
                elif name == 'opt-table-header-promotion': opts.table_header_promotion = val
                elif name == 'opt-table-presentation-tables': opts.table_presentation_tables = val
                elif name == 'opt-table-skip-empty-rows': opts.table_skip_empty_rows = val
                handled = True
                break
        if handled:
            i += 1
            continue
        if a.startswith('-'):
            name = a.split('=',1)[0]
            raise ValueError('unknown flag: ' + name)
        positionals.append(a)
        i += 1
    if positionals:
        raise RuntimeError('unknown arguments: ' + ' '.join(positionals))

    if opts.strong_delim not in ('**','__'):
        raise ValueError(f'invalid value for --opt-strong-delimiter="{opts.strong_delim}" must be exactly 2 characters of "**" or "__"')
    if opts.table_newline_behavior not in ('skip','preserve'):
        raise ValueError(f'error while initializing "table" plugin: unknown value "{opts.table_newline_behavior}" for newline behavior')
    if opts.table_span_cell_behavior not in ('empty','mirror'):
        raise ValueError(f'error while initializing "table" plugin: unknown value "{opts.table_span_cell_behavior}" for span cell behavior')
    if opts.table_cell_padding not in ('aligned','minimal','none'):
        raise ValueError(f'error while initializing "table" plugin: unknown value "{opts.table_cell_padding}" for cell padding behavior')
    # parse selectors early enough to report an invalid selector
    try:
        opts._include_parsed = [parse_selector_group(s) for s in opts.include_selectors]
        opts._exclude_parsed = [parse_selector_group(s) for s in opts.exclude_selectors]
    except SelectorError as e:
        raise ValueError(str(e))
    return opts

# ---------------- Selector support ----------------

class SelectorError(Exception):
    pass

class SimpleSelector:
    def __init__(self):
        self.tag = None
        self.any = False
        self.id = None
        self.classes = []
        self.attrs = []
        self.first_child = False
        self.not_sel = None

_IDENT = re.compile(r'[A-Za-z_][A-Za-z0-9_-]*|\*')

def parse_selector_group(s):
    if s == '[':
        raise SelectorError('invalid value "[" for flag -include-selector: invalid css selector: expected identifier, found EOF instead')
    groups = []
    for part in split_commas(s):
        part = part.strip()
        if not part:
            continue
        seq = []
        for piece in re.split(r'\s+', part):
            if piece:
                seq.append(parse_simple_selector(piece))
        if seq:
            groups.append(seq)
    return groups

def split_commas(s):
    res=[]; cur=''; depth=0
    for ch in s:
        if ch in '([': depth+=1
        elif ch in ')]' and depth: depth-=1
        if ch == ',' and depth == 0:
            res.append(cur); cur=''
        else:
            cur += ch
    res.append(cur)
    return res

def parse_simple_selector(s):
    sel = SimpleSelector()
    pos = 0
    m = _IDENT.match(s, pos)
    if m:
        tok = m.group(0)
        if tok == '*': sel.any = True
        else: sel.tag = tok.lower()
        pos = m.end()
    while pos < len(s):
        ch = s[pos]
        if ch == '#':
            pos += 1; m = re.match(r'[A-Za-z0-9_-]+', s[pos:])
            if not m: raise SelectorError(f'invalid css selector: {s}')
            sel.id = m.group(0); pos += len(m.group(0))
        elif ch == '.':
            pos += 1; m = re.match(r'[A-Za-z0-9_-]+', s[pos:])
            if not m: raise SelectorError(f'invalid css selector: {s}')
            sel.classes.append(m.group(0)); pos += len(m.group(0))
        elif ch == '[':
            end = s.find(']', pos+1)
            if end < 0: raise SelectorError(f'invalid css selector: {s}')
            body = s[pos+1:end].strip()
            if '=' in body:
                k,v = body.split('=',1); k=k.strip().lower(); v=v.strip().strip('"\'')
                sel.attrs.append((k,v))
            elif body:
                sel.attrs.append((body.lower(), None))
            pos = end+1
        elif s.startswith(':first-child', pos):
            sel.first_child = True; pos += len(':first-child')
        elif s.startswith(':not(', pos):
            depth=1; j=pos+5
            while j < len(s) and depth:
                if s[j] == '(': depth += 1
                elif s[j] == ')': depth -= 1
                j += 1
            inner = s[pos+5:j-1]
            sel.not_sel = parse_simple_selector(inner)
            pos = j
        else:
            raise SelectorError(f'invalid css selector: {s}')
    return sel

def element_children(parent):
    return [c for c in parent.children if not c.is_text()]

def matches_simple(node, sel):
    if node.is_text(): return False
    if node.tag == 'root':
        # The original treats an implicit document body as selectable.
        if sel.tag not in (None, 'body', 'html') and not sel.any:
            return False
    else:
        if sel.tag and node.tag != sel.tag:
            return False
    if sel.id is not None and node.attr('id') != sel.id:
        return False
    classes = node.attr('class').split()
    for c in sel.classes:
        if c not in classes: return False
    for k,v in sel.attrs:
        if k not in node.attrs: return False
        if v is not None and node.attrs.get(k) != v: return False
    if sel.first_child:
        if not node.parent: return False
        elems = element_children(node.parent)
        if not elems or elems[0] is not node: return False
    if sel.not_sel is not None and matches_simple(node, sel.not_sel):
        return False
    return True

def matches_sequence(node, seq):
    if not seq: return False
    if not matches_simple(node, seq[-1]): return False
    anc = node.parent
    for sel in reversed(seq[:-1]):
        found = False
        while anc is not None:
            if matches_simple(anc, sel):
                found = True
                anc = anc.parent
                break
            anc = anc.parent
        if not found: return False
    return True

def matches_any_group(node, parsed_groups_list):
    for groups in parsed_groups_list:
        for seq in groups:
            if matches_sequence(node, seq):
                return True
    return False

def clone_node(node):
    n = Node(node.tag, dict(node.attrs), node.text)
    for c in node.children:
        n.append(clone_node(c))
    return n

def apply_selectors(root, opts):
    if getattr(opts, '_include_parsed', None):
        newroot = Node('root')
        def walk(n, ancestor_selected=False):
            if not n.is_text() and matches_any_group(n, opts._include_parsed):
                if not ancestor_selected:
                    newroot.append(clone_node(n))
                return
            for c in n.children:
                if not c.is_text():
                    walk(c, ancestor_selected)
        # Special case: body/html/* matching the root means include all content.
        if matches_any_group(root, opts._include_parsed):
            newroot = clone_node(root)
        else:
            walk(root)
        root = newroot
    if getattr(opts, '_exclude_parsed', None):
        def filter_children(n):
            kept=[]
            for c in n.children:
                if not c.is_text() and matches_any_group(c, opts._exclude_parsed):
                    continue
                if not c.is_text():
                    filter_children(c)
                kept.append(c)
            n.children = kept
            for c in kept: c.parent = n
        if matches_any_group(root, opts._exclude_parsed):
            root.children = []
        else:
            filter_children(root)
    return root

# ---------------- Text escaping ----------------

def normalize_ws(s):
    return re.sub(r'[ \t\r\n\f]+', ' ', s)

def escape_alt(s):
    return s.replace('\\','\\\\').replace('[','\\[').replace(']','\\]')

def escape_delims(line, link_text=False):
    out=[]; i=0; n=len(line)
    while i<n:
        ch=line[i]
        if ch == '\\':
            out.append('\\\\'); i += 1; continue
        if ch == '<':
            out.append('&lt;'); i += 1; continue
        if ch == '>':
            out.append('&gt;'); i += 1; continue
        if ch == '`':
            out.append('\\`'); i += 1; continue
        if ch == '[':
            if link_text or (']' in line[i+1:]): out.append('\\[')
            else: out.append('[')
            i += 1; continue
        if ch == ']':
            out.append('\\]' if link_text else ']'); i += 1; continue
        if ch in '*_':
            j=i
            while j<n and line[j]==ch: j+=1
            run=j-i
            prev=line[i-1] if i>0 else ''
            nxt=line[j] if j<n else ''
            prev_space=(prev=='' or prev.isspace())
            next_space=(nxt=='' or nxt.isspace())
            esc_count=0
            if run == 1:
                if ch == '*':
                    if not (prev_space and next_space): esc_count=1
                else:
                    if (not next_space and prev_space) or (not prev_space and not next_space): esc_count=1
            else:
                if prev_space and next_space:
                    esc_count = run-1 if line.strip(ch).strip()=='' else 1
                elif not next_space:
                    esc_count = run
                else:
                    esc_count = 1
            out.append(('\\'+ch)*esc_count + ch*(run-esc_count))
            i=j; continue
        out.append(ch); i += 1
    return ''.join(out)

def apply_line_start_escape(line):
    if not line or line.startswith('\\'):
        return line
    # Leading/trailing spaces are normally stripped by the caller; keep the common cases exact.
    if re.match(r'^#{1,6}(\s|$)', line):
        return '\\' + line
    if re.match(r'^[*+-](\s|$)', line):
        return '\\' + line
    m = re.match(r'^(\d+)([.)])(\s|$)', line)
    if m:
        return m.group(1) + '\\' + line[len(m.group(1)):]
    if re.fullmatch(r'-{3,}', line):
        return '\\' + line
    return line

def escape_text(s, line_start=True, link_text=False):
    s = normalize_ws(s)
    parts = s.split('\n')
    res=[]
    for p in parts:
        e = escape_delims(p, link_text=link_text)
        if line_start:
            e = apply_line_start_escape(e)
        res.append(e)
    return '\n'.join(res)

# ---------------- Rendering ----------------

class Renderer:
    def __init__(self, opts):
        self.opts = opts

    def convert(self, html):
        p = TreeBuilder()
        try:
            p.feed(html)
            p.close()
        except Exception:
            pass
        root = apply_selectors(p.root, self.opts)
        out = self.render_block_children(root, {})
        return self.final_trim(out)

    def final_trim(self, s):
        # Match the command's habit of returning content without the terminal newline.
        lines = s.split('\n')
        # trim blank lines at both ends
        while lines and lines[0].strip() == '': lines.pop(0)
        while lines and lines[-1].strip() == '': lines.pop()
        return '\n'.join(lines)

    def is_block(self, node):
        return (not node.is_text()) and node.tag in BLOCK_TAGS and node.tag not in ('td','th','tr','tbody','thead','tfoot')

    def render_block_children(self, node, ctx):
        blocks=[]; inline=[]
        def flush():
            nonlocal inline
            if inline:
                txt = self.render_inline_nodes(inline, ctx)
                txt = self.tidy_inline(txt)
                if txt.strip():
                    blocks.append(txt)
                inline=[]
        for c in node.children:
            if c.is_text():
                if normalize_ws(c.text).strip(): inline.append(c)
            elif self.is_block(c):
                flush()
                b = self.render_block(c, ctx)
                if b.strip(): blocks.append(b)
            else:
                inline.append(c)
        flush()
        return '\n\n'.join(blocks)

    def render_block(self, node, ctx):
        tag = node.tag
        if tag in ('html','body','root'):
            return self.render_block_children(node, ctx)
        if tag in ('p','div','section','article','header','footer','main','aside','nav','figure','figcaption','address','center','form','fieldset','legend','details','summary','dialog'):
            # If it contains block children, render as a block container; otherwise as a paragraph.
            if any((not c.is_text()) and self.is_block(c) for c in node.children):
                return self.render_block_children(node, ctx)
            return self.tidy_inline(self.render_inline_nodes(node.children, ctx)).strip()
        if tag in ('h1','h2','h3','h4','h5','h6'):
            content = self.tidy_inline(self.render_inline_nodes(node.children, ctx)).strip()
            if not content: return ''
            level = int(tag[1])
            return '#' * level + ' ' + content
        if tag == 'hr':
            return '* * *'
        if tag == 'pre':
            return self.render_pre(node)
        if tag == 'blockquote':
            subctx = dict(ctx); subctx['blockquote'] = True
            content = self.render_block_children(node, subctx)
            content = self.final_trim(content)
            if not content: return ''
            return '\n'.join('> ' + line if line != '' else '> ' for line in content.split('\n'))
        if tag in ('ul','ol'):
            return self.render_list(node, tag == 'ol', ctx)
        if tag == 'li':
            return self.render_block_children(node, ctx)
        if tag == 'dl':
            return self.render_block_children(node, ctx)
        if tag in ('dt','dd'):
            return self.tidy_inline(self.render_inline_nodes(node.children, ctx)).strip()
        if tag == 'table':
            if self.opts.plugin_table and (self.opts.table_presentation_tables or node.attr('role').lower() != 'presentation'):
                table = self.render_table(node, ctx)
                if table is not None:
                    return table
                return self.render_table_fallback_blocks(node, ctx)
            return self.render_table_plain(node, ctx)
        return self.render_block_children(node, ctx)

    def render_inline_nodes(self, nodes, ctx, link_text=False):
        out=[]; i=0
        while i < len(nodes):
            n = nodes[i]
            if n.is_text():
                text = escape_text(n.text, line_start=not ctx.get('blockquote'), link_text=link_text)
                out.append(text)
                i += 1; continue
            # Merge immediately adjacent <code> nodes, matching observed behavior for code runs.
            if n.tag == 'code':
                raw = []
                j = i
                while j < len(nodes) and (not nodes[j].is_text()) and nodes[j].tag == 'code':
                    raw.append(text_content(nodes[j], br_as_newline=False))
                    j += 1
                out.append(render_code_span(''.join(raw)))
                i = j; continue
            out.append(self.render_inline(n, ctx, link_text=link_text))
            i += 1
        return ''.join(out)

    def render_inline(self, node, ctx, link_text=False):
        tag = node.tag
        if tag == 'br': return BR
        if tag in ('strong','b'):
            content = self.tidy_inline(self.render_inline_nodes(node.children, ctx, link_text=link_text)).strip()
            return (self.opts.strong_delim + content + self.opts.strong_delim) if content else ''
        if tag in ('em','i'):
            content = self.tidy_inline(self.render_inline_nodes(node.children, ctx, link_text=link_text)).strip()
            return ('*' + content + '*') if content else ''
        if tag in ('del','s','strike'):
            content = self.tidy_inline(self.render_inline_nodes(node.children, ctx, link_text=link_text)).strip()
            if not content: return ''
            return '~~' + content + '~~' if self.opts.plugin_strikethrough else content
        if tag == 'a':
            content = self.tidy_inline(self.render_inline_nodes(node.children, ctx, link_text=True)).strip()
            href = node.attr('href')
            href = self.make_url(href, is_image=False)
            title = node.attr('title')
            return '[' + content + '](' + href + self.title_part(title) + ')'
        if tag == 'img':
            src = node.attr('src')
            if src == '': return ''
            alt = escape_alt(node.attr('alt'))
            title = node.attr('title')
            return '![' + alt + '](' + self.make_url(src, is_image=True) + self.title_part(title) + ')'
        if tag == 'code':
            return render_code_span(text_content(node, br_as_newline=False))
        if tag == 'pre':
            return self.render_pre(node)
        if tag == 'hr':
            return '* * *'
        if tag in ('ul','ol','blockquote','table','div','p','section','article'):
            return self.render_block(node, ctx)
        # Transparent/unknown inline tags.
        return self.render_inline_nodes(node.children, ctx, link_text=link_text)

    def tidy_inline(self, s):
        if not s: return ''
        # Convert BR markers. Leading/trailing br markers disappear; a single marker is a hard break,
        # consecutive markers are a blank line.
        parts=[]; i=0; n=len(s)
        while i<n:
            if s[i] == BR:
                j=i
                while j<n and s[j] == BR: j += 1
                # only add a break if there is non-space content on both sides
                before=''.join(parts).rstrip(' ')
                after=s[j:]
                if before.strip() and after.strip():
                    parts = [before]
                    parts.append('\n\n' if j-i >= 2 else '  \n')
                else:
                    parts = [before]
                i=j
            else:
                parts.append(s[i]); i += 1
        s=''.join(parts)
        # For each line, trim ordinary and unicode whitespace at the edges; preserve hard-break two spaces.
        lines=s.split('\n')
        cleaned=[]
        for line in lines:
            if line.endswith('  '):
                core=line[:-2].strip()
                cleaned.append((core + '  ') if core else '')
            else:
                cleaned.append(line.strip())
        # Trim blank lines at edges.
        while cleaned and cleaned[0] == '': cleaned.pop(0)
        while cleaned and cleaned[-1] == '': cleaned.pop()
        return '\n'.join(cleaned)

    def render_list(self, node, ordered, ctx):
        items=[c for c in node.children if (not c.is_text()) and c.tag == 'li']
        lines=[]
        start = 1
        if ordered:
            try: start = int(node.attr('start') or '1')
            except Exception: start = 1
        idx=start
        for li in items:
            content = self.render_block_children(li, ctx)
            content = self.final_trim(content)
            if not content.strip():
                idx += 1
                continue
            marker = (str(idx) + '. ') if ordered else '- '
            indent = ' ' * len(marker)
            clines = content.split('\n')
            first = marker + clines[0]
            rest = [indent + l for l in clines[1:]]
            lines.append('\n'.join([first] + rest))
            idx += 1
        return '\n'.join(lines)

    def render_pre(self, node):
        lang=''
        raw=''
        code_child = None
        for c in node.children:
            if not c.is_text() and c.tag == 'code':
                code_child = c; break
        if code_child is not None:
            raw = text_content(code_child, br_as_newline=True)
            cls = code_child.attr('class')
            for part in cls.split():
                if part.startswith('language-') and len(part) > len('language-'):
                    lang = part[len('language-'):]; break
                if part.startswith('lang-') and len(part) > len('lang-'):
                    lang = part[len('lang-'):]; break
        else:
            raw = text_content(node, br_as_newline=True)
            if raw.startswith('\n'):
                raw = raw[1:]
        if raw.endswith('\n'):
            raw = raw[:-1]
        maxrun=2
        for m in re.finditer(r'`+', raw):
            maxrun=max(maxrun, len(m.group(0)))
        fence='`'*(maxrun+1 if maxrun>=3 else 3)
        return fence + lang + '\n' + raw + '\n' + fence

    def make_url(self, url, is_image=False):
        if self.opts.domain is not None:
            url = urljoin(self.opts.domain, url)
        return quote(url, safe="/%#:?&=@+$,;~-_.!'")

    def title_part(self, title):
        if title == '': return ''
        if '"' in title and "'" not in title:
            return " '" + title + "'"
        title = title.replace('"','\\"')
        return ' "' + title + '"'

    def render_table_plain(self, node, ctx):
        # Without the plugin, table structural tags collapse and their textual contents flow together.
        return self.tidy_inline(self.render_inline_all(node, ctx)).strip()

    def render_inline_all(self, node, ctx):
        out=[]
        for c in node.children:
            if c.is_text(): out.append(escape_text(c.text, line_start=not ctx.get('blockquote')))
            elif c.tag == 'br': out.append(BR)
            elif c.tag == 'img': out.append(self.render_inline(c, ctx))
            else: out.append(self.render_inline_all(c, ctx))
        return ''.join(out)

    def table_rows(self, table):
        rows=[]
        def walk(n):
            if n.is_text(): return
            if n.tag == 'tr': rows.append(n); return
            for c in n.children: walk(c)
        walk(table)
        return rows

    def render_table(self, node, ctx):
        rows_nodes = self.table_rows(node)
        rows=[]; aligns=[]; row_has_th=[]
        for tr in rows_nodes:
            cells=[]; hasth=False; row_align=[]
            for cell in tr.children:
                if cell.is_text() or cell.tag not in ('td','th'): continue
                hasth = hasth or (cell.tag == 'th')
                txt = self.tidy_inline(self.render_inline_nodes(cell.children, dict(ctx, table=True))).strip()
                colspan = 1
                try: colspan = max(1, int(cell.attr('colspan') or '1'))
                except Exception: colspan = 1
                align = (cell.attr('align') or '').lower()
                if not align:
                    style = cell.attr('style').lower()
                    m = re.search(r'text-align\s*:\s*(left|right|center)', style)
                    if m: align = m.group(1)
                for k in range(colspan):
                    cells.append(txt if (k == 0 or self.opts.table_span_cell_behavior == 'mirror') else '')
                    row_align.append(align)
            if self.opts.table_skip_empty_rows and all(not c.strip() for c in cells):
                continue
            rows.append(cells); aligns.append(row_align); row_has_th.append(hasth)
        if not rows:
            return ''
        # If newlines are present and preservation was not requested, decline table conversion.
        if self.opts.table_newline_behavior != 'preserve':
            for r in rows:
                for c in r:
                    if '\n' in c:
                        return None
        else:
            rows = [[c.replace('\n','<br />') for c in r] for r in rows]
        ncols = max((len(r) for r in rows), default=0)
        if ncols == 0: return ''
        for r in rows:
            while len(r) < ncols: r.append('')
        for a in aligns:
            while len(a) < ncols: a.append('')
        if row_has_th and row_has_th[0]:
            header = rows[0]; body = rows[1:]; header_align = aligns[0]
        elif self.opts.table_header_promotion:
            header = rows[0]; body = rows[1:]; header_align = aligns[0]
        else:
            header = [''] * ncols; body = rows; header_align = [''] * ncols
        return self.format_table(header, body, header_align)

    def format_table(self, header, body, aligns):
        mode = self.opts.table_cell_padding
        rows=[header]+body
        widths=[0]*len(header)
        for r in rows:
            for i,c in enumerate(r): widths[i]=max(widths[i], len(c))
        if mode == 'none':
            def row(r): return '|' + '|'.join(r) + '|'
            sep=[]
            for a in aligns:
                sep.append(':--' if a=='left' else ':-:' if a=='center' else '--:' if a=='right' else '---')
            return '\n'.join([row(header), '|'+'|'.join(sep)+'|'] + [row(r) for r in body])
        if mode == 'minimal':
            def row(r): return '| ' + ' | '.join(r) + ' |'
            sep=[]
            for a in aligns:
                sep.append(':--' if a=='left' else ':-:' if a=='center' else '--:' if a=='right' else '---')
            return '\n'.join([row(header), '|'+ '|'.join(sep) + '|'] + [row(r) for r in body])
        # aligned
        def row(r):
            return '| ' + ' | '.join((r[i].ljust(widths[i]) for i in range(len(widths)))) + ' |'
        sep=[]
        for i,a in enumerate(aligns):
            w=widths[i]
            if a=='left': sep.append(':' + '-'*(w+1))
            elif a=='center': sep.append(':' + '-'*max(w,1) + ':')
            elif a=='right': sep.append('-'*(w+1) + ':')
            else: sep.append('-'*(w+2))
        return '\n'.join([row(header), '|' + '|'.join(sep) + '|'] + [row(r) for r in body])

    def render_table_fallback_blocks(self, node, ctx):
        blocks=[]
        for tr in self.table_rows(node):
            for cell in tr.children:
                if not cell.is_text() and cell.tag in ('td','th'):
                    txt = self.tidy_inline(self.render_inline_nodes(cell.children, ctx)).strip()
                    if txt: blocks.append(txt)
        return '\n\n'.join(blocks)

def text_content(node, br_as_newline=True):
    if node.is_text(): return node.text
    if node.tag == 'br': return '\n' if br_as_newline else ''
    return ''.join(text_content(c, br_as_newline=br_as_newline) for c in node.children)

def render_code_span(raw):
    raw = re.sub(r'[ \t\r\n\f]+', ' ', raw).strip()
    if raw == '': return ''
    maxrun=0
    for m in re.finditer(r'`+', raw): maxrun=max(maxrun, len(m.group(0)))
    ticks='`'*(maxrun+1 if maxrun else 1)
    if maxrun:
        return ticks + ' ' + raw + ' ' + ticks
    return ticks + raw + ticks

# ---------------- File I/O ----------------

def output_name_for_input(path):
    base=os.path.basename(path)
    stem=os.path.splitext(base)[0]
    return stem + '.md'

def write_output(path, content, overwrite):
    if os.path.isdir(path) and not path.endswith('/'):
        return err(f'path "{path}" exists and is a directory, did you mean "{path}/"?', DIR_HINT)
    if os.path.exists(path) and not overwrite:
        return err(f'output path "{path}" already exists. Use --output-overwrite to replace existing files')
    parent=os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
    return 0

def process(opts):
    renderer = Renderer(opts)
    if opts.input is not None:
        matches = sorted(glob.glob(opts.input))
        if not matches:
            return err(f'no files found matching pattern "{opts.input}"', GLOB_HINT)
        if len(matches) == 1 and os.path.isdir(matches[0]):
            return err(f'input path "{matches[0]}" is a directory, not a file', GLOB_HINT)
        for m in matches:
            if os.path.isdir(m):
                return err(f'input path "{m}" is a directory, not a file', GLOB_HINT)
        multiple = len(matches) > 1
        if opts.output and os.path.isdir(opts.output) and not opts.output.endswith('/'):
            return err(f'path "{opts.output}" exists and is a directory, did you mean "{opts.output}/"?', DIR_HINT)
        if multiple:
            if not opts.output:
                return err('when processing multiple input files --output needs to be a directory', GLOB_HINT)
            if not opts.output.endswith('/'):
                return err(f'when processing multiple input files, --output "{opts.output}" must end with "{opts.output}/" to indicate a directory')
        if opts.output and opts.output.endswith('/'):
            os.makedirs(opts.output, exist_ok=True)
            for m in matches:
                with open(m, 'r', encoding='utf-8', errors='replace') as f: html=f.read()
                content=renderer.convert(html)
                target=os.path.join(opts.output, output_name_for_input(m))
                if os.path.exists(target) and not opts.output_overwrite:
                    return err(f'output path "{opts.output}" already exists. Use --output-overwrite to replace existing files')
                with open(target, 'w', encoding='utf-8') as f: f.write(content)
            return 0
        if opts.output:
            with open(matches[0], 'r', encoding='utf-8', errors='replace') as f: html=f.read()
            return write_output(opts.output, renderer.convert(html), opts.output_overwrite)
        else:
            with open(matches[0], 'r', encoding='utf-8', errors='replace') as f: html=f.read()
            sys.stdout.write(renderer.convert(html) + '\n')
            return 0
    else:
        try:
            mode=os.fstat(sys.stdin.fileno()).st_mode
            if stat.S_ISCHR(mode):
                return err('the html input should be piped into the cli', CLI_HINT)
        except Exception:
            pass
        html=sys.stdin.read()
        content=renderer.convert(html)
        if opts.output:
            if os.path.isdir(opts.output) and not opts.output.endswith('/'):
                return err(f'path "{opts.output}" exists and is a directory, did you mean "{opts.output}/"?', DIR_HINT)
            if opts.output.endswith('/'):
                os.makedirs(opts.output, exist_ok=True)
                target=os.path.join(opts.output, 'output.md')
                if os.path.exists(target) and not opts.output_overwrite:
                    return err(f'output path "{opts.output}" already exists. Use --output-overwrite to replace existing files')
                with open(target, 'w', encoding='utf-8') as f: f.write(content)
                return 0
            return write_output(opts.output, content, opts.output_overwrite)
        sys.stdout.write(content + '\n')
        return 0

def main(argv):
    try:
        opts=parse_args(argv)
    except SystemExit as e:
        return int(e.code)
    except RuntimeError as e:
        return err(str(e), CLI_HINT)
    except ValueError as e:
        return err(str(e))
    return process(opts)

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
